import sys

def solve():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    idx = 1

    dice = []
    K_list = []

    # Parse the dice configurations
    for _ in range(N):
        K = int(input_data[idx])
        K_list.append(K)
        idx += 1

        freq = {}
        for k in range(idx, idx + K):
            val = int(input_data[k])
            freq[val] = freq.get(val, 0) + 1
        idx += K
        dice.append(freq)

    # Track the maximum probability using a fraction (max_num / max_den)
    # to avoid any possible floating-point precision issues during comparisons.
    max_num = 0
    max_den = 1

    # Compare every pair of dice to find the maximum probability
    for i in range(N):
        dict1 = dice[i]
        k1 = K_list[i]
        for j in range(i + 1, N):
            dict2 = dice[j]
            k2 = K_list[j]

            # To optimize the intersection, iterate over the smaller dictionary
            if len(dict1) > len(dict2):
                d1, d2 = dict2, dict1
            else:
                d1, d2 = dict1, dict2

            match_sum = 0
            for val, count in d1.items():
                if val in d2:
                    match_sum += count * d2[val]

            # The probability of rolling the same number is match_sum / (k1 * k2)
            # Use cross-multiplication for exact comparison
            if match_sum * max_den > max_num * (k1 * k2):
                max_num = match_sum
                max_den = k1 * k2

    # Output the exact maximum probability found as a float
    print(max_num / max_den)

